begin;

select public.seed_cipmn_mock_module('CIPMN-MOD-012','[["Needs-driven and context-specific design","A donor proposes copying a successful urban water intervention into a remote rural community without a local needs assessment.","Conduct contextual needs assessment and community consultation, then redesign the intervention for local conditions.","Replicate the original design unchanged because prior success proves universal suitability.","Begin procurement before understanding the target population.","Use only donor headquarters data and exclude local evidence.","International programmes should be grounded in specific needs, culture, institutions, infrastructure and environmental conditions."],["Participatory stakeholder engagement","Programme design is completed by external consultants without meaningful participation by beneficiaries, local government or marginalised groups.","Create an inclusive participatory process that gives affected stakeholders a real role in design, decisions and evaluation.","Inform communities only after all major decisions are final.","Consult only national officials because beneficiaries lack technical expertise.","Invite marginalised groups for attendance but exclude their input from decisions.","Participation builds relevance, ownership, trust and sustainability and should include groups often excluded from decision-making."],["Alignment with global and national priorities","A proposed health programme cites an SDG but conflicts with national sector policy and duplicates an existing government initiative.","Map objectives to relevant global and national priorities and coordinate with responsible institutions to resolve duplication.","Use the SDG reference as sufficient justification.","Ignore national policy because donor priorities take precedence.","Proceed independently to preserve programme visibility.","Effective international programmes align global commitments with national plans, sector policy and institutional ownership."],["Evidence-based planning","A programme is designed from assumptions and anecdotes despite available baseline data, evaluations and sector research.","Validate the problem and intervention logic using credible data, research and lessons from prior programmes.","Use only the most favourable anecdote to support funding.","Delay all data collection until final evaluation.","Exclude prior lessons because the new programme has a different donor.","Evidence-based planning improves relevance, design quality, decision-making and adaptive management."],["Results-oriented management","Reports count workshops and funds spent but do not show changes in behaviour, services or beneficiary outcomes.","Define a results chain with indicators that connect activities and outputs to outcomes and intended impact.","Treat expenditure as the primary measure of development success.","Report only activities because outcomes are outside programme control.","Increase the number of workshops without reviewing effectiveness.","Results-oriented management focuses on the causal path from inputs and activities to outputs, outcomes and impact."],["Sustainability and capacity building","External advisers operate the programme''s core systems while local institutions receive little training or authority.","Embed capacity transfer, local ownership and institutional strengthening throughout implementation.","Retain external control until the final day and hand over immediately.","Limit local staff to administrative support.","Assume capacity will develop automatically through observation.","Sustainability depends on local capability, ownership, systems and resources rather than prolonged external dependence."],["Accountability and transparency","Beneficiaries cannot see selection criteria or report misuse, and financial decisions are not documented for audit.","Establish transparent criteria, accessible feedback and complaint channels, documented decisions and auditable controls.","Keep criteria confidential to prevent questions.","Allow only donor staff to raise complaints.","Record financial decisions only when an audit is announced.","Development programmes require accountability to donors, governments, partners and affected populations through transparent and auditable systems."],["Adaptive management","Monitoring shows that an intervention is not reaching the intended group, but the team refuses to adjust because the original workplan was approved.","Use the evidence to test assumptions, consult stakeholders and adapt implementation through authorised governance.","Continue unchanged so spending remains on schedule.","Make undocumented changes without donor or partner visibility.","Suppress the monitoring result until the annual review.","Adaptive management uses timely evidence and learning to adjust while preserving accountability and strategic intent."],["Theory of Change","A programme lists activities but cannot explain why they should lead to the intended social outcome or what assumptions must hold.","Develop a Theory of Change that makes causal pathways, assumptions, actors and contextual conditions explicit.","Add more activities without examining causal logic.","Use the budget as the programme theory.","Replace the outcome with a list of deliverables.","A Theory of Change explains how and why change is expected, including assumptions, pathways and external influences."],["Logical Framework","The team needs a concise management structure linking objectives, indicators, verification sources and assumptions.","Develop a logical framework aligned with the Theory of Change and programme results chain.","Use a stakeholder register as the results framework.","Record only the overall goal and omit indicators.","Treat assumptions as guaranteed facts.","A Log Frame summarises intervention logic, objectively verifiable indicators, means of verification and key assumptions."],["SWOT, PESTEL and stakeholder mapping","A country-entry decision must consider organisational capability, political change, economic volatility, regulation and influential local actors.","Use SWOT for internal and external strategic position, PESTEL for macro context and stakeholder mapping for actor influence and interests.","Use only a Gantt chart to assess the country context.","Apply stakeholder mapping to calculate programme budget.","Use SWOT as a replacement for evidence and consultation.","The tools answer different but complementary questions about capability, external context and stakeholder dynamics."],["Portfolio strategic alignment and value maximisation","A portfolio funds many individually attractive projects, but several do not contribute to organisational strategy and compete for scarce resources.","Review, prioritise, rebalance or terminate components based on strategic contribution, value, risk and resource capacity.","Continue all components because each has already received approval.","Prioritise solely by which project has spent the most.","Allocate equal resources regardless of strategic value.","Portfolio management optimises the collective set of investments for strategy, value, risk and resource use."],["Cross-cultural portfolio governance","A governance model assumes one communication and decision style across countries, causing misunderstanding and weak local ownership.","Design clear common governance while adapting engagement and decision practices to cultural and institutional contexts.","Allow each country to operate without any shared standards.","Impose headquarters practices without explanation or adaptation.","Treat cultural differences as resistance to discipline.","International governance needs consistent accountability and context-sensitive ways of working across cultures and institutions."],["Donor compliance and audit readiness","A partner charges costs to a grant without required supporting documents and applies procurement rules inconsistently.","Correct the control weakness, verify allowability, retain evidence, train the partner and monitor compliance before further exposure.","Approve the costs because the activities were useful.","Create supporting documents retrospectively without verification.","Wait for the donor audit before addressing the weakness.","Donor-funded programmes require documented allowability, procurement compliance, ethical controls and continuous audit readiness."],["Partnership, exit and sustainability planning","A sub-grantee relationship has unclear roles, recurring conflict and no plan for local ownership or programme exit.","Clarify the partnership through agreed governance and MoU terms, resolve conflicts, transfer capacity and define measurable exit and sustainability criteria.","Extend external funding indefinitely to avoid an exit decision.","Terminate the partner immediately without analysing causes or obligations.","Keep roles informal so the relationship remains flexible.","Effective partnerships need clear roles, coordination, conflict mechanisms, capacity transfer and planned transition to sustainable local ownership."]]'::jsonb);

do $verify$
declare v_pid uuid;
begin
  select id into v_pid from public.programmes where code='CIPMN-MOCK' and is_active=true;
  if v_pid is null then raise exception 'CIPMN-MOCK programme missing.'; end if;
  if (select count(*) from public.examinations where programme_id=v_pid and status='published')<>12 then
    raise exception 'Expected 12 published CIPMN mock examinations.';
  end if;
  if exists(select 1 from public.examinations e where e.programme_id=v_pid and
    (select count(*) from public.questions q where q.examination_id=e.id and q.is_active=true)<>75) then
    raise exception 'Every CIPMN mock examination must contain exactly 75 active questions.';
  end if;
  if (select count(*) from public.questions q join public.examinations e on e.id=q.examination_id
      where e.programme_id=v_pid and q.is_active=true)<>900 then
    raise exception 'Expected 900 active CIPMN mock questions.';
  end if;
end;
$verify$;

commit;
